CREATE VIEW public.v_meeting_funnel AS SELECT NULL::text AS meeting_id, NULL::date AS meeting_date, NULL::text AS hotel_id, NULL::text AS hotel_name, NULL::text AS status, NULL::text AS service_line, NULL::text AS ae_owner_id, NULL::text AS orm_team, NULL::text AS orm_owner_id, NULL::text AS marcom_owner_id, NULL::text AS tier, NULL::integer AS scheduled, NULL::integer AS confirmed, NULL::integer AS completed, NULL::integer AS survey, NULL::integer AS postponed_next_month, true AS pending_sync FROM public.crm_documents WHERE false;
CREATE VIEW public.v_meeting_count_by_ae AS SELECT meeting_id, meeting_date, hotel_id, hotel_name, status, service_line, ae_owner_id, orm_team, orm_owner_id, marcom_owner_id, NULL::integer AS meeting_count, pending_sync FROM public.v_meeting_funnel WHERE false;
CREATE VIEW public.v_meeting_survey_collection AS SELECT meeting_id, meeting_date, hotel_id, hotel_name, status, service_line, ae_owner_id, orm_team, orm_owner_id, marcom_owner_id, completed, NULL::integer AS submitted, NULL::integer AS queue, pending_sync FROM public.v_meeting_funnel WHERE false;
CREATE VIEW public.v_meeting_completion AS SELECT meeting_id, meeting_date, hotel_id, hotel_name, status, service_line, ae_owner_id, orm_team, orm_owner_id, marcom_owner_id, scheduled, completed, postponed_next_month, pending_sync FROM public.v_meeting_funnel WHERE false;
CREATE VIEW public.v_meeting_survey_scores AS SELECT meeting_id, meeting_date, hotel_id, hotel_name, status, service_line, ae_owner_id, orm_team, orm_owner_id, marcom_owner_id, NULL::text AS question, NULL::numeric AS score, NULL::text AS subject_owner_id, NULL::text AS comment, true AS pending_sync FROM public.v_meeting_funnel WHERE false;
CREATE VIEW public.v_meeting_flags AS SELECT meeting_id, meeting_date, hotel_id, hotel_name, status, service_line, ae_owner_id, orm_team, orm_owner_id, marcom_owner_id, NULL::text AS topic, NULL::integer AS red_count, NULL::integer AS warn_count, NULL::integer AS warning_progress, NULL::integer AS age_days, NULL::text AS route_target, NULL::text AS comment, NULL::date AS resolved_at, true AS pending_sync FROM public.v_meeting_funnel WHERE false;
CREATE VIEW public.v_meeting_rubric_summary AS SELECT NULL::numeric AS average_score, NULL::text AS verdict_tier, NULL::jsonb AS category_breakdown, true AS pending_engine WHERE false;
GRANT SELECT ON public.v_meeting_funnel, public.v_meeting_count_by_ae, public.v_meeting_survey_collection, public.v_meeting_completion, public.v_meeting_survey_scores, public.v_meeting_flags, public.v_meeting_rubric_summary TO anon, authenticated, service_role;
COMMENT ON VIEW public.v_meeting_funnel IS 'Pending existing Meeting mirror: AE Workspace meetings/surveys/flags are browser mocks, not synced entities. No inferred meetings from contracts. Replace empty projection only after canonical meeting mirror and hotel-month caretaker history exist; no current-owner fallback.';
COMMENT ON VIEW public.v_meeting_count_by_ae IS 'Pending canonical meeting mirror and monthly caretaker history; no inferred person attribution.';
COMMENT ON VIEW public.v_meeting_survey_collection IS 'Pending canonical meeting/survey mirrors; submitted divided by completed, never confirmed.';
COMMENT ON VIEW public.v_meeting_completion IS 'Pending canonical meeting mirror. MTD Completed / (Scheduled minus next-month postponements).';
COMMENT ON VIEW public.v_meeting_survey_scores IS 'Pending survey mirror and exact hotel-month caretaker history. Q8 referral signal is not NPS. DM12 falls back only within same-month account caretaker.';
COMMENT ON VIEW public.v_meeting_flags IS 'Pending canonical flag mirror and hotel-month caretaker history. No flag recomputation from mock/current owners. Warning window configuration and aging topic dictionary absent; do not invent persisted config.';
COMMENT ON VIEW public.v_meeting_rubric_summary IS 'Pending rubric engine; ORM monthly strategy only. No scores or weights inferred.';